const syncBookCopyCounts = `-- name: SyncBookCopyCounts :exec
UPDATE books b
SET
    total_copies = (SELECT COUNT(*) FROM book_copies WHERE book_id = b.id),
    available_copies = (SELECT COUNT(*) FROM book_copies WHERE book_id = b.id AND status = 'available'),
    updated_at = NOW()
WHERE b.id = $1 AND b.deleted_at IS NULL
`

// Sync total_copies and available_copies from book_copies table
func (q *Queries) SyncBookCopyCounts(ctx context.Context, id int32) error {
	_, err := q.db.Exec(ctx, syncBookCopyCounts, id)
	return err
}

const updateBook = `-- name: UpdateBook :one
UPDATE books
SET book_id = $2, book_type = $3, isbn = $4, title = $5, author = $6, publisher = $7, published_year = $8, genre = $9, description = $10, cover_image_url = $11, total_copies = $12, available_copies = $13, shelf_location = $14, category_id = $15, series_id = $16, series_number = $17, language = $18, page_count = $19, edition = $20, format = $21, updated_at = NOW()
WHERE id = $1 AND deleted_at IS NULL
RETURNING id, book_id, isbn, title, author, publisher, published_year, genre, description, cover_image_url, total_copies, available_copies, shelf_location, is_active, deleted_at, created_at, updated_at, condition, category_id, series_id, series_number, language, page_count, edition, format, book_type
`

type UpdateBookParams struct {
	ID              int32       `db:"id" json:"id"`
	BookID          string      `db:"book_id" json:"book_id"`
	BookType        interface{} `db:"book_type" json:"book_type"`
	Isbn            pgtype.Text `db:"isbn" json:"isbn"`
	Title           string      `db:"title" json:"title"`
	Author          string      `db:"author" json:"author"`
	Publisher       pgtype.Text `db:"publisher" json:"publisher"`
	PublishedYear   pgtype.Int4 `db:"published_year" json:"published_year"`
	Genre           pgtype.Text `db:"genre" json:"genre"`
	Description     pgtype.Text `db:"description" json:"description"`
	CoverImageUrl   pgtype.Text `db:"cover_image_url" json:"cover_image_url"`
	TotalCopies     pgtype.Int4 `db:"total_copies" json:"total_copies"`
	AvailableCopies pgtype.Int4 `db:"available_copies" json:"available_copies"`
	ShelfLocation   pgtype.Text `db:"shelf_location" json:"shelf_location"`
	CategoryID      pgtype.Int4 `db:"category_id" json:"category_id"`
	SeriesID        pgtype.Int4 `db:"series_id" json:"series_id"`
	SeriesNumber    pgtype.Int4 `db:"series_number" json:"series_number"`
	Language        pgtype.Text `db:"language" json:"language"`
	PageCount       pgtype.Int4 `db:"page_count" json:"page_count"`
	Edition         pgtype.Text `db:"edition" json:"edition"`
	Format          pgtype.Text `db:"format" json:"format"`
}

func (q *Queries) UpdateBook(ctx context.Context, arg UpdateBookParams) (Book, error) {
	row := q.db.QueryRow(ctx, updateBook,
		arg.ID,
		arg.BookID,
		arg.BookType,
		arg.Isbn,
		arg.Title,
		arg.Author,
		arg.Publisher,
		arg.PublishedYear,
		arg.Genre,
		arg.Description,
		arg.CoverImageUrl,
		arg.TotalCopies,
		arg.AvailableCopies,
		arg.ShelfLocation,
		arg.CategoryID,
		arg.SeriesID,
		arg.SeriesNumber,
		arg.Language,
		arg.PageCount,
		arg.Edition,
		arg.Format,
	)
	var i Book
	err := row.Scan(
		&i.ID,
		&i.BookID,
		&i.Isbn,
		&i.Title,
		&i.Author,
		&i.Publisher,
		&i.PublishedYear,
		&i.Genre,
		&i.Description,
		&i.CoverImageUrl,
		&i.TotalCopies,
		&i.AvailableCopies,
		&i.ShelfLocation,
		&i.IsActive,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Condition,
		&i.CategoryID,
		&i.SeriesID,
		&i.SeriesNumber,
		&i.Language,
		&i.PageCount,
		&i.Edition,
		&i.Format,
		&i.BookType,
	)
	return i, err
}

